   457  std::string StringPrimitive::_snapshotNameImpl(GCCell *cell, GC *gc) {
   458    auto *const self = vmcast<StringPrimitive>(cell);
   459    // Only convert up to EXTERNAL_STRING_THRESHOLD characters, because large
   460    // strings can cause crashes in the snapshot visualizer.
   461    std::string out;
   462    bool fullyWritten = true;
   463    if (self->isASCII()) {
   464      auto ref = self->castToASCIIRef();
   465      out = std::string{ref.begin(),
   466                        std::min(
   467                            static_cast<uint32_t>(ref.size()),
   468                            toRValue(EXTERNAL_STRING_THRESHOLD))};
   469      fullyWritten = ref.size() <= EXTERNAL_STRING_THRESHOLD;
   470    } else {
   471      fullyWritten = convertUTF16ToUTF8WithReplacements(
   472          out, self->castToUTF16Ref(), EXTERNAL_STRING_THRESHOLD);
   473    }
   474    if (!fullyWritten) {
   475      // The string was truncated, add a truncation message
   476      out += "...(truncated by snapshot)...";
   477    }
   478    return out;
